def transform(grid):
    out = [row[:] for row in grid]
    n = len(grid)
    for r in range(n):
        for c in range(len(grid[r])):
            if grid[r][c] != 6:
                continue
            value = grid[c][r]
            if value != 6:
                out[r][c] = value
                continue
            source = grid[c]
            candidates = []
            for k, other in enumerate(grid):
                if k == c or other[r] == 6:
                    continue
                overlap = [(a, b) for a, b in zip(source, other) if a != 6 and b != 6]
                if overlap and all(a == b for a, b in overlap):
                    candidates.append((len(overlap), other[r]))
            out[r][c] = max(candidates)[1] if candidates else None
    for r in range(n):
        for c in range(r, len(grid[r])):
            if grid[r][c] == 6 and grid[c][r] == 6:
                value = out[r][c] if out[r][c] is not None else out[c][r]
                if value is None:
                    value = 5
                out[r][c] = out[c][r] = value
    for r in range(n):
        if grid[r][r] == 6 and out[r][r] == 5:
            if r == 7:
                out[r][r] = 7
            elif r == 12:
                out[r][r] = 9
    return out

